function o(r,e=1){const t=Math.floor(Number(r));return Number.isFinite(t)&&t>0?t:e}function s(r){const e=String(r??"").replace(/\D/g,"");if(!e)return 0;const t=Number(e);return Number.isFinite(t)&&t>0?t:0}function c(r,e){const t=o(e),a=r.reduce((n,u)=>Math.max(n,s(u)),0);return Math.max(t,a+1)}function m(r,e){const t=o(e),a=r.reduce((n,u)=>{const i=String(u??"").trim();return/^\d+$/.test(i)?Math.max(n,Number(i)):n},0);return Math.max(t,a+1)}function N(r){return String(Math.max(1,Math.floor(Number(r)||1))).padStart(5,"0")}export{c as a,N as f,m as g};
